  const code = (error as { body?: { error?: string } })?.body?.error;
  return (code && ERROR_TEXT[code]) || (error instanceof Error ? error.message : "操作失败，请重试");
}

function resultsBlock(result: PollResults, poll: PollDetail): HTMLElement {
